import React, { useEffect, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  LabelList
} from "recharts";

interface ProfitAndLossType {
  day: string;
  loss: string;
  profit: string;
}

interface ProfitAndLossWithPercentType extends ProfitAndLossType {
  lossPercent: number;
  profitPercent: number;
  percent: number;
}

interface ProfitAndLossByDaysProps {
  data: ProfitAndLossType[];
}

export default function ProfitAndLossByDays({ data }: ProfitAndLossByDaysProps) {
  const [myData, setMyData] = useState<ProfitAndLossWithPercentType[]>([]);

  useEffect(() => {
    const dataWithPercentages = data.map((item) => {
      const parsedProfit = parseFloat(`${item.profit}`).toFixed(2);
      const parsedLoss = parseFloat(`${item.loss}`).toFixed(2);
      const total = Math.abs(+parsedLoss) + Math.abs(+parsedProfit);

      // возвращаем новый объект, исходный data не мутируется
      return {
        ...item,
        lossPercent: +((Math.abs(+parsedLoss) / total) * 100).toFixed(2),
        profitPercent: +((Math.abs(+parsedProfit) / total) * 100).toFixed(2),
        percent: 100,
      };
    });

    setMyData(dataWithPercentages);
  }, [data]);

  // кастомный лейбл для profit: dataKey = profitPercent, отображаем profit
  const ProfitLabel = (props: any) => {
    const { x, y, width, height, index } = props;
    const entry = myData[index];
    if (!entry) return null;

    return (
      <text
        x={x + width / 2}
        y={y + height / 2}
        fill="#B0B0B0"
        fontSize={13}
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {entry.profit}
      </text>
    );
  };

  // кастомный лейбл для loss: dataKey = lossPercent, отображаем loss
  const LossLabel = (props: any) => {
    const { x, y, width, height, index } = props;
    const entry = myData[index];
    if (!entry) return null;

    return (
      <text
        x={x + width / 2}
        y={y + height / 2}
        fill="#fff"
        fontSize={13}
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {entry.loss}
      </text>
    );
  };

  return (
    <ResponsiveContainer width="100%" height={260}>
      <BarChart
        width={500}
        data={myData}
        margin={{
          top: 20,
          right: 30,
          left: 20,
          bottom: 5
        }}
      >
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="day" />
        <Tooltip />
        <Bar
          dataKey="profitPercent"
          radius={[9, 9, 9, 9]}
          barSize={60}
          stackId="a"
          fill="#89ADA0"
        >
          <LabelList dataKey="profitPercent" content={<ProfitLabel />} />
        </Bar>
        <Bar
          dataKey="lossPercent"
          radius={[9, 9, 9, 9]}
          barSize={60}
          stackId="a"
          fill="#ECECEC"
        >
          <LabelList dataKey="lossPercent" content={<LossLabel />} />
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  );
}
```

Что сделано:

1. **Проценты через useEffect и useState**
   - Расчёт перенесён в `useEffect` с зависимостью `[data]`.
   - Результат сетается в `myData` через `setMyData`.
   - `map` возвращает новые объекты (`...item`), поэтому пропс `data` не изменяется.
   - В `BarChart` теперь передаётся `data={myData}`.
   - Заодно поправил `XAxis dataKey` на `"day"` — в интерфейсе поле называется `day`, а не `name`.

2. **Кастомные LabelList**
   - `ProfitLabel` и `LossLabel` — компоненты, которые recharts вызывает для каждого сегмента бара. В `props` приходят координаты сегмента (`x, y, width, height`) и `index` строки данных.
   - По `index` берём соответствующую запись из `myData` и выводим исходное значение: для `profitPercent` — `entry.profit`, для `lossPercent` — `entry.loss`.
   - Лейблы центрируются внутри своего сегмента бара (`textAnchor="middle"`, `dominantBaseline="middle"`). Если хочешь расположить их иначе — например, над сегментом — замени `y={y + height / 2}` на `y={y - 6}` (и убери `dominantBaseline`).

Небольшое замечание: белый текст (`#fff`) на светло-сером фоне `#ECECEC` будет плохо читаться — возможно, стоит взять более тёмный цвет для лейбла loss, например `#9A9A9A`.

